import json
import os

import httpx


def _value_at(payload, path):
    current = payload
    for part in path.split('.'):
        if part.endswith(']') and '[' in part:
            name, index = part[:-1].split('[', 1)
            if name:
                current = current[name]
            current = current[int(index)]
        else:
            current = current[part]
    return current


